/* A stroke gradient requires lineStyle, retains fill/width and has versioned method visibility. */
#include "gradient_spread_fixture.hpp"
int main()
{
    FVM_Config cfg;FVM_Runtime *rt=0;assert(fvm_config_init(&cfg)==FVM_OK && fvm_runtime_create(&cfg,&rt)==FVM_OK);
    for(unsigned version=0;version<=8;++version){FVM_Context *c=0;assert(fvm_context_create(rt,&c)==FVM_OK);if(version){unsigned char swf[]={'F','W','S',8,16,0,0,0,8,0,0,12,1,0,0,0};swf[3]=(unsigned char)version;assert(fvm_load_memory(c,swf,sizeof(swf))==FVM_OK);}assert(fvm_standard_install(c)==FVM_OK);FVM_Object *clip=0;assert(fvm_movieclip_create(c,"line",1,&clip)==FVM_OK && fvm_gc_pin(c,clip)==FVM_OK);FVM_Value a[8],out,method;spread_arguments(c,a,1);assert(fvm_object_get(c,clip,"lineGradientStyle",&method)==FVM_OK);if(version && version<8){assert(method.type==FVM_VALUE_UNDEFINED);fvm_context_destroy(c);continue;}assert(method.type==FVM_VALUE_OBJECT);FVM_Object *data=clip->resource_result.object;assert(fvm_object_call(c,clip,"lineGradientStyle",8,a,&out)==FVM_OK && data->properties.find("lineGradient")==data->properties.end());FVM_Value line[3];fvm_value_number(line,4);fvm_value_number(line+1,0x00ff00);fvm_value_number(line+2,50);assert(fvm_object_call(c,clip,"lineStyle",3,line,&out)==FVM_OK && fvm_object_call(c,clip,"beginGradientFill",5,a,&out)==FVM_OK);FVM_Object *fill=data->properties["gradient"].object;assert(fvm_object_call(c,clip,"lineGradientStyle",8,a,&out)==FVM_OK);FVM_Object *record=data->properties["lineGradient"].object;assert(record && record!=fill && record->properties["spread"].number==1 && data->properties["gradient"].object==fill && data->properties["width"].number==4 && data->properties["lineAlpha"].number==50);assert(fvm_value_string(a+5,"unknown-spread")==FVM_OK && fvm_object_call(c,clip,"lineGradientStyle",6,a,&out)==FVM_UNSUPPORTED && data->properties["lineGradient"].object==record);assert(fvm_gc_collect(c,0)==FVM_OK && !c->gc_frames && !c->gc_native_depth);fvm_context_destroy(c);}
    fvm_runtime_destroy(rt);return 0;
}
